    private boolean dialogClick(android.view.accessibility.AccessibilityNodeInfo node,String label){if(node==null)return false;if(node.getText()!=null && node.getText().toString().equalsIgnoreCase(label) && node.isEnabled() && node.isClickable())return node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);for(int i=0;i<node.getChildCount();i++)if(dialogClick(node.getChild(i),label))return true;return false;}
    private void dialogTap(String label)throws Exception{instrumentation.waitForIdleSync();long end=android.os.SystemClock.uptimeMillis()+5000;boolean activated=false;while(!activated && android.os.SystemClock.uptimeMillis()<end){activated=dialogClick(instrumentation.getUiAutomation().getRootInActiveWindow(),label);if(!activated)Thread.sleep(25);}assertTrue("Dialog action "+label,activated);instrumentation.waitForIdleSync();}
