    @Test public void nativeChecklistHandleDragMovesTheItemWithoutEditingItsText()throws Exception{
        Note seed=note("Drag list").list("Drag list",Arrays.asList(new Note.Item("first","First",true,1),new Note.Item("second","Second",false,0)),false,System.currentTimeMillis());start(Collections.singletonList(seed));main(()->controller.openNote(seed.id));await(()->text("Reorder list item 1")!=null);closeKeyboard();await(()->{TextView handle=text("Reorder list item 1");return itemInputs().size()==2 && handle!=null && handle.getWidth()>0 && !handle.isLayoutRequested() && controller.view().hasWindowFocus() && !keyboardVisibleForTest();});final float[] points=new float[4];main(()->{View handle=text("Reorder list item 1"),row=(View)itemInputs().get(1).getParent();android.graphics.Rect source=new android.graphics.Rect(),target=new android.graphics.Rect();assertTrue(handle.getGlobalVisibleRect(source));assertTrue(row.getGlobalVisibleRect(target));points[0]=source.exactCenterX();points[1]=source.exactCenterY();points[2]=target.exactCenterX();points[3]=target.top+target.height()*.8f;});
        long now=android.os.SystemClock.uptimeMillis();for(int i=0;i<=9;i++){int action=i==0?MotionEvent.ACTION_DOWN:i==9?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE;float fraction=Math.min(1,i/8f);MotionEvent event=MotionEvent.obtain(now,android.os.SystemClock.uptimeMillis(),action,points[0]+(points[2]-points[0])*fraction,points[1]+(points[3]-points[1])*fraction,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{assertTrue("Checklist drag injection must be accepted",instrumentation.getUiAutomation().injectInputEvent(event,true));}finally{event.recycle();}if(i<9)android.os.SystemClock.sleep(25);}
        try{await(()->itemInputs().size()==2 && itemInputs().get(0).getText().toString().equals("Second"));}catch(AssertionError failure){final String[] state={"unavailable"};main(()->{try{java.lang.reflect.Field field=NotesController.class.getDeclaredField("checklistDragState");field.setAccessible(true);state[0]=String.valueOf(field.get(controller));}catch(ReflectiveOperationException ignored){}});try{storeScreenshot("checklist-drag-failure",instrumentation.getUiAutomation().takeScreenshot());}catch(Exception | AssertionError capture){failure.addSuppressed(capture);}throw new AssertionError("Checklist drag did not reorder: phase="+state[0],failure);}saved();List<Note.Item> rows=new NotesRepository(context).load().get(0).items;assertEquals("second",rows.get(0).id);assertEquals("first",rows.get(1).id);assertEquals("First",rows.get(1).text);assertTrue(rows.get(1).checked);assertEquals(1,rows.get(1).depth);tap("Undo");saved();assertEquals("first",new NotesRepository(context).load().get(0).items.get(0).id);
    }
