    // Synthetic recognizer result: renders review UI without claiming OCR accuracy or running ML.
    private void showSyntheticOcrReview(String value,String target){main(()->{try{
        java.lang.reflect.Constructor<OfflineOcr.Result> constructor=OfflineOcr.Result.class.getDeclaredConstructor(String.class,String.class,int.class,int.class,int.class);constructor.setAccessible(true);OfflineOcr.Result result=constructor.newInstance(value,"eng",72,1200,800);
        for(String name:new String[]{"title","body","search"}){java.lang.reflect.Field field=NotesController.class.getDeclaredField(name);field.setAccessible(true);field.set(controller,null);}
        java.lang.reflect.Field editing=NotesController.class.getDeclaredField("editing");editing.setAccessible(true);editing.set(controller,target);java.lang.reflect.Field panel=NotesController.class.getDeclaredField("ocrPanel");panel.setAccessible(true);panel.setBoolean(controller,true);
        java.lang.reflect.Method render=NotesController.class.getDeclaredMethod("renderOcrReview",OfflineOcr.Result.class,String.class);render.setAccessible(true);render.invoke(controller,result,target);
    }catch(ReflectiveOperationException failure){throw new AssertionError("Cannot render synthetic OCR review",failure);}});instrumentation.waitForIdleSync();}
