    private android.view.accessibility.AccessibilityNodeInfo dialogInput(android.view.accessibility.AccessibilityNodeInfo root){if(root==null)return null;if("android.widget.EditText".contentEquals(root.getClassName()))return root;for(int i=0;i<root.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo found=dialogInput(root.getChild(i));if(found!=null)return found;}return null;}
