    private void documentLaidOut(String key)throws Exception{await(()->canonicalField(key)!=null && canonicalField(key).getLayout()!=null && !canonicalField(key).isLayoutRequested() && controller.view().hasWindowFocus());instrumentation.waitForIdleSync();CountDownLatch frames=new CountDownLatch(1);main(()->controller.view().postOnAnimation(()->controller.view().postOnAnimation(frames::countDown)));assertTrue("Canonical focus/layout frames settled",frames.await(5,TimeUnit.SECONDS));}
    private void nativeDocumentDrag(String sourceTag,String targetTag,boolean section)throws Exception{
        closeKeyboard();documentLaidOut("title");final float[] points=new float[4];main(()->{View handle=controller.view().findViewWithTag(sourceTag);assertNotNull(handle);android.graphics.Rect visible=new android.graphics.Rect();assertTrue(handle.getGlobalVisibleRect(visible));points[0]=visible.exactCenterX();points[1]=visible.exactCenterY();});long now=android.os.SystemClock.uptimeMillis();
        for(int i=0;i<=12;i++){main(()->{View handle=controller.view().findViewWithTag(targetTag);assertNotNull(handle);View target=(View)handle.getParent();if(section)target=(View)target.getParent();android.graphics.Rect visible=new android.graphics.Rect();assertTrue(target.getGlobalVisibleRect(visible));assertTrue("The target's lower half must be visible",visible.height()>target.getHeight()*.75f);int[] location=new int[2];target.getLocationOnScreen(location);points[2]=visible.exactCenterX();points[3]=location[1]+target.getHeight()*.65f;});float fraction=Math.min(1,i/11f);MotionEvent event=MotionEvent.obtain(now,android.os.SystemClock.uptimeMillis(),i==0?MotionEvent.ACTION_DOWN:i==12?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE,points[0]+(points[2]-points[0])*fraction,points[1]+(points[3]-points[1])*fraction,0);event.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);try{assertTrue("Native document drag event accepted",instrumentation.getUiAutomation().injectInputEvent(event,true));}finally{event.recycle();}if(i<12)android.os.SystemClock.sleep(30);}
    }
